// The golden for `derive inventories` (stele#396, Done when): a real
// captured plan set from a release, derived again and compared with the
// documents that release shipped — byte-identical, the creation time
// and the creator tool's version aside.
//
// Every directory under testdata/inventories is one set, laid out as
// testdata/inventories/README.md describes. A set whose name starts
// with "interim-" is NOT a capture: it was generated by this code and
// proves only that the harness runs, never that the derivation matches
// a release. The Done-when row is met by a captured set alone.

package cli

import (
	"bytes"
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"slices"
	"strings"
	"testing"

	"github.com/monumental-archive/stele/internal/cargo"
	"github.com/monumental-archive/stele/internal/jsonx"
)

const goldenSets = "testdata/inventories"

// goldenInputs is a set's inputs.json: the release's own facts, as the
// publish run passed them.
type goldenInputs struct {
	Repo            string `json:"repo"`
	Version         string `json:"version"`
	Created         string `json:"created"`
	Name            string `json:"name"`
	Classes         string `json:"classes"`
	EvidenceClasses string `json:"evidenceClasses"`
	Machinery       string `json:"machineryVersion"`
	Variants        string `json:"variants"`
	// Run names the publish run the plans were downloaded from.
	Run string `json:"run"`
}

// capturedSelection is one cargo/index.json row: a closure
// selection's cargo flags and the file holding its captured metadata.
type capturedSelection struct {
	Flags string `json:"flags"`
	File  string `json:"file"`
}

// capturedResolver serves the cargo metadata captured per selection.
type capturedResolver struct {
	t     *testing.T
	dir   string
	index []capturedSelection
}

func (r capturedResolver) Metadata(_ string, sel cargo.Selection) ([]byte, error) {
	key := strings.Join(sel.Args(), " ")

	i := slices.IndexFunc(r.index, func(c capturedSelection) bool { return c.Flags == key })
	if i < 0 {
		r.t.Fatalf("no captured cargo metadata for selection %q", key)
	}

	file := r.index[i].File

	raw, err := os.ReadFile(filepath.Join(r.dir, "cargo", file)) //nolint:gosec // the set's own fixture
	if err != nil {
		return nil, fmt.Errorf("captured metadata %s: %w", file, err)
	}

	return raw, nil
}

// volatile masks what a re-derivation cannot reproduce: the instant
// the document was created and the version of the tool that created
// it.
var volatile = regexp.MustCompile(`"created":"[^"]*"|"creators":\["Tool: [^"]*"\]`)

func TestDeriveInventoriesGolden(t *testing.T) {
	sets, err := os.ReadDir(goldenSets)
	if err != nil {
		t.Fatal(err)
	}

	if len(sets) == 0 {
		t.Fatal("no golden set: the Done-when row needs a captured plan set")
	}

	for _, set := range sets {
		if !set.IsDir() {
			continue
		}

		t.Run(set.Name(), func(t *testing.T) {
			goldenSet(t, filepath.Join(goldenSets, set.Name()))
		})
	}
}

func goldenSet(t *testing.T, dir string) {
	t.Helper()

	in := readJSON[goldenInputs](t, filepath.Join(dir, "inputs.json"))
	index := readJSON[[]capturedSelection](t, filepath.Join(dir, "cargo", "index.json"))

	withResolver(t, capturedResolver{t: t, dir: dir, index: *index})

	plans, err := filepath.Glob(filepath.Join(dir, "plans", "*", "plan.json"))
	if err != nil || len(plans) == 0 {
		t.Fatalf("no plans in %s (%v)", dir, err)
	}

	out := t.TempDir()

	args := []string{
		"inventories", "--policy", filepath.Join(dir, "assert-policy.json"),
		"--classes", in.Classes, "--repo", in.Repo, "--version", in.Version, "--created", in.Created,
		"--name", in.Name, "--tree", dir, "--out-dir", out, "--variants", in.Variants,
		"--evidence-classes", in.EvidenceClasses, "--machinery-version", in.Machinery,
	}

	var stdout, stderr bytes.Buffer

	if code := deriveCmd(append(args, plans...), &stdout, &stderr); code != exitOK {
		t.Fatalf("deriveCmd = %d (stderr: %s)", code, stderr.String())
	}

	// Shipped bytes are kept as .golden so no formatter touches them.
	shipped, err := filepath.Glob(filepath.Join(dir, "shipped", "*.golden"))
	if err != nil || len(shipped) == 0 {
		t.Fatalf("no shipped documents in %s (%v)", dir, err)
	}

	var derived []string

	entries, err := os.ReadDir(out)
	if err != nil {
		t.Fatal(err)
	}

	for _, e := range entries {
		derived = append(derived, e.Name())
	}

	var names []string

	for _, path := range shipped {
		name := strings.TrimSuffix(filepath.Base(path), ".golden")
		names = append(names, name)

		want, rerr := os.ReadFile(path) //nolint:gosec // the set's own fixture
		if rerr != nil {
			t.Fatal(rerr)
		}

		got, rerr := os.ReadFile(filepath.Join(out, name)) //nolint:gosec // the test's own temp file
		if rerr != nil {
			t.Errorf("%s shipped but was not derived (derived: %v)", name, derived)

			continue
		}

		if !bytes.Equal(volatile.ReplaceAll(got, nil), volatile.ReplaceAll(want, nil)) {
			t.Errorf("%s differs from what the release shipped\ngot:  %s\nwant: %s", name, got, want)
		}
	}

	for _, name := range derived {
		if !slices.Contains(names, name) {
			t.Errorf("%s was derived but the release shipped no such document", name)
		}
	}
}

func readJSON[T any](t *testing.T, path string) *T {
	t.Helper()

	raw, err := os.ReadFile(path) //nolint:gosec // the set's own fixture
	if err != nil {
		t.Fatal(err)
	}

	v, err := jsonx.DecodeForeign[T](raw)
	if err != nil {
		t.Fatalf("%s: %v", path, err)
	}

	return v
}
